mapper.select:
SELECT al.id, al.pass_code_id, al.visitor_id, v.name AS visitorName, al.appointment_id, a.appoint_no AS appointmentNo, al.action, al.gate_location, al.result, al.deny_reason, al.operator_id, al.created_at FROM access_log al LEFT JOIN visitor v ON al.visitor_id = v.id LEFT JOIN appointment a ON al.appointment_id = a.id
AND al.visitor_id = #{visitorId}
AND al.appointment_id = #{appointmentId}
ORDER BY al.created_at DESC
